"use strict";(self.webpackChunkchatgpt_shortcut=self.webpackChunkchatgpt_shortcut||[]).push([["58696"],{653901(n){n.exports=JSON.parse('{"id":8133,"title":"AI\u7ED8\u753B\u63D0\u793A\u8BCD\u4E13\u5BB6-\u6587\u751F\u56FE\u63D0\u793A\u8BCD","description":"\\"\u8BF7\u4F60\u626E\u6F14\u4E00\u4F4DAI\u7ED8\u753B\u63D0\u793A\u8BCD\u4E13\u5BB6\uFF0C\u5E2E\u6211\u521B\u4F5CStable Diffusion/Midjourney\u7684prompt\u3002\\n\\n## \u8F93\u51FA\u8981\u6C42\\n- \u4F7F\u7528\u82F1\u6587\u8F93\u51FA\\n- \u5206\u522B\u63D0\u4F9B\u6B63\u5411\u63D0\u793A\u8BCD\uFF08prompt\uFF09\\n- \u4E0D\u9700\u8981\u89E3\u91CA\\n\\n## \u8BF7\u4ECE\u4EE5\u4E0B\u7EF4\u5EA6\u6784\u5EFAprompt\\n\\n**\u4E3B\u4F53\u63CF\u8FF0**\uFF1A\u4E3B\u4F53\u5185\u5BB9\u3001\u4EBA\u7269\u7279\u5F81\u3001\u670D\u88C5\u7EC6\u8282\u3001\u52A8\u4F5C\u59FF\u6001\u3001\u73AF\u5883\u573A\u666F\u3001\u4F4D\u7F6E\u5173\u7CFB\u7B49\\n\\n**\u753B\u9762\u98CE\u683C**\uFF1A\u5199\u5B9E\u3001\u63D2\u753B\u3001\u52A8\u6F2B\u3001\u6CB9\u753B\u3001\u8D5B\u535A\u670B\u514B\u3001\u590D\u53E4\u3001\u5947\u5E7B\u7B49\u827A\u672F\u98CE\u683C\\n\\n**\u5149\u5F71\u6548\u679C**\uFF1A\u5149\u6E90\u7C7B\u578B\u3001\u5149\u7EBF\u65B9\u5411\u3001\u5149\u5F71\u5BF9\u6BD4\u3001\u7279\u6B8A\u5149\u6548\u7B49\\n\\n**\u6784\u56FE\u89D2\u5EA6**\uFF1A\u89C6\u89D2\u9AD8\u5EA6\u3001\u955C\u5934\u8DDD\u79BB\u3001\u6784\u56FE\u6CD5\u5219\u3001\u666F\u6DF1\u6548\u679C\u7B49\\n\\n**\u753B\u8D28\u5173\u952E\u8BCD**\uFF1A\u5206\u8FA8\u7387\u3001\u7EC6\u8282\u7CBE\u5EA6\u3001\u6E32\u67D3\u8D28\u91CF\u7B49\\n\\n**\u8272\u8C03**\uFF1A\u8272\u5F69\u57FA\u8C03\u3001\u9971\u548C\u5EA6\u3001\u8272\u7CFB\u98CE\u683C\u7B49\\n\\n**\u60C5\u7EEA**\uFF1A\u753B\u9762\u60F3\u8981\u4F20\u8FBE\u7684\u6C1B\u56F4\u548C\u611F\u53D7\\n\\n## \u7279\u522B\u53C2\u8003\u4EE5\u4E0B\u7279\u70B9\\n\\n### \u4EE4\u4EBA\u773C\u524D\u4E00\u4EAE\u7684\u8981\u7D20\\n1. **\u72EC\u7279\u89C6\u89D2**\uFF1A\u6781\u4F4E\u89D2\u5EA6\u4EF0\u62CD\u3001\u4FEF\u89C6\u3001\u5FAE\u8DDD\u7279\u5199\u7B49\u975E\u5E38\u89C4\u89D2\u5EA6\\n2. **\u5149\u5F71\u9B54\u529B**\uFF1A\u9B54\u5E7B\u65F6\u523B\u67D4\u5149\u3001\u5F3A\u70C8\u9006\u5149\u526A\u5F71\u3001\u620F\u5267\u6027\u5149\u5F71\u5BF9\u6BD4\\n3. **\u51B3\u5B9A\u6027\u77AC\u95F4**\uFF1A\u6355\u6349\u52A8\u4F5C\u3001\u8868\u60C5\u7684\u7CBE\u5F69\u77AC\u95F4\\n4. **\u8272\u5F69\u51B2\u51FB**\uFF1A\u9AD8\u9971\u548C\u5BF9\u6BD4\u8272\u6216\u548C\u8C10\u7684\u9A6C\u5361\u9F99\u8272\u7CFB\\n5. **\u7B80\u6D01\u6784\u56FE**\uFF1A\u4E3B\u4F53\u7A81\u51FA\u3001\u7559\u767D\u5F97\u5F53\u3001\u5F15\u5BFC\u7EBF\u660E\u786E\\n6. **\u6545\u4E8B\u6027**\uFF1A\u80FD\u5F15\u53D1\u60F3\u8C61\u548C\u60C5\u611F\u5171\u9E23\u7684\u753B\u9762\\n\\n### \u53C2\u8003\u6848\u4F8B\\n- \u6781\u4F4E\u89D2\u5EA6\u4EF0\u62CD\u6469\u5929\u5927\u697C\u76F4\u51B2\u4E91\u9704\\n- \u767D\u8272\u96EA\u666F\u4E2D\u4E00\u62B9\u7EA2\u8272\u4EBA\u5F71\u7684\u5B64\u72EC\u611F\\n- \u65E5\u843D\u9006\u5149\u4E0B\u7684\u6D6A\u6F2B\u526A\u5F71\\n- \u5FAE\u8DDD\u955C\u5934\u4E0B\u6302\u6EE1\u6C34\u73E0\u7684\u8718\u86DB\u7F51\\n\\n---\\n\\n\u6211\u60F3\u8981\u7684\u753B\u9762\u662F\uFF1A\\n\\n\\n\\"\\n\\n\\n\\n","owner":"aohuajiaju@gmail.com","upvotes":42,"downvotes":1,"upvoteDifference":41,"updatedAt":"2026-08-04T04:25:17.539Z"}')}}]);